const W=1200,H=760;
const colors=state=>state.theme==='dark'?{paper:'#11130f',ink:'#f4f3e9'}:{paper:'#f4f4ef',ink:'#191b16'};
export function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;(document.querySelector('dialog[open]')||document.body).append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function wrapText(ctx,text,maxWidth){const lines=[];for(const line of text.split('\n')){let current='';for(const character of line){if(ctx.measureText(current+character).width>maxWidth&&current){lines.push(current);current=character;}else current+=character;}lines.push(current);}return lines;}
export async function renderCard(state,plantCanvas,side,{border=true}={}){
 const canvas=document.createElement('canvas');canvas.width=W*2;canvas.height=H*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);const {paper,ink}=colors(state);ctx.fillStyle=paper;ctx.fillRect(0,0,W,H);ctx.fillStyle=ink;
 if(side==='front'){
  ctx.save();ctx.translate(W/2,0);ctx.scale(.73,1);ctx.textAlign='center';ctx.textBaseline='top';ctx.font=(state.title.length>14?Math.max(75,200*14/state.title.length):200)+'px Georgia, "Songti SC", serif';ctx.letterSpacing='-13px';
  const title=state.title||'Gift Card';const span=ctx.measureText(title).width;if(span>1500)ctx.scale(1500/span,1);ctx.fillText(title,0,30);ctx.restore();ctx.drawImage(plantCanvas,0,0,W,H);
 }else{
  ctx.fillStyle=ink;ctx.font='13px Arial';ctx.letterSpacing='2px';ctx.fillText('A LITTLE LOVE, JUST FOR YOU',85,110);ctx.letterSpacing='0px';ctx.font='72px Georgia, "Songti SC", serif';
  const recipient='For '+(state.to||'you')+'.';const recipientLines=wrapText(ctx,recipient,690).slice(0,2);recipientLines.forEach((line,i)=>ctx.fillText(line,85,210+i*80));
  const messageY=recipientLines.length>1?350:290;ctx.font='25px Georgia, "Songti SC", serif';const lines=wrapText(ctx,state.message,660);const lineHeight=Math.min(42,(600-messageY)/Math.max(1,lines.length));
  lines.forEach((line,i)=>ctx.fillText(line,85,messageY+i*lineHeight));ctx.font='20px Georgia, "Songti SC", serif';ctx.fillText('With love, '+(state.from||'我'),85,670);ctx.font='italic 14px Georgia';ctx.fillText('Romantic Garden',85,720);
 }
 if(side==='back'&&plantCanvas)ctx.drawImage(plantCanvas,0,0,W,H);
 if(border){ctx.strokeStyle=ink;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(1,1,W-2,H-2,35);ctx.stroke();}return canvas;
}
export async function exportPNG(state,plantCanvas,backCanvas,download=true){
 const front=await renderCard(state,plantCanvas,'front'),back=await renderCard(state,backCanvas,'back');
 // A single image contains both sides so browsers need only one download permission.
 const page=document.createElement('canvas');page.width=2500;page.height=3240;const ctx=page.getContext('2d');ctx.fillStyle=colors(state).paper;ctx.fillRect(0,0,page.width,page.height);ctx.drawImage(front,50,50);ctx.drawImage(back,50,1670);
 const blob=await new Promise(resolve=>page.toBlob(resolve,'image/png'));if(!blob)throw Error('无法生成图片');if(download)downloadBlob(blob,'给'+(state.to||'你')+'的花朵卡片.png');return blob;
}
export async function exportInteractive(state,plantCanvas,layers,backCanvas,backLayers,download=true){
 const back=await renderCard(state,null,'back');const payload={state,layers,backLayers,back:back.toDataURL('image/png')};
 const encoded=JSON.stringify(payload).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
 const html=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>给你的一束花</title><style>
 *{box-sizing:border-box}body{margin:0;min-height:100svh;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#f4f4ef;color:#191b16;font-family:Georgia,'Songti SC',serif;padding:35px 22px;overflow-x:hidden}.note{font:11px Arial,sans-serif;letter-spacing:2px;opacity:.55;margin-bottom:38px}.wrap{width:min(760px,90vw);aspect-ratio:1200/760;perspective:1400px}.tilt,.flip{width:100%;height:100%;transform-style:preserve-3d;position:relative}.flip{transition:transform .7s cubic-bezier(.23,1,.32,1)}.flip.back{transform:rotateY(180deg)}.face{position:absolute;inset:0;border:1px solid currentColor;border-radius:24px;overflow:hidden;backface-visibility:hidden;-webkit-backface-visibility:hidden;box-shadow:0 28px 60px #0002}.backface{transform:rotateY(180deg)}.board{width:1200px;height:760px;transform-origin:top left;position:absolute;left:0;top:0;overflow:hidden}.board h1{position:absolute;top:30px;left:0;width:1200px;font:200px/.95 Georgia,'Songti SC',serif;letter-spacing:-13px;text-align:center;transform:scaleX(.73);transform-origin:center top;margin:0;white-space:pre}.layer{position:absolute;inset:0;width:1200px;height:760px;pointer-events:none}.back-background{position:absolute;inset:0;width:1200px;height:760px;object-fit:fill}.actions{display:flex;gap:12px;align-items:center;margin-top:38px}button{font:12px Arial,sans-serif;border:1px solid currentColor;border-radius:25px;background:transparent;color:inherit;padding:12px 22px;cursor:pointer}button:focus-visible{outline:2px solid currentColor;outline-offset:5px}.signature{font-size:14px;margin-top:25px;opacity:.6}.hint{font:10px Arial,sans-serif;opacity:.5;margin-top:18px}@media(prefers-reduced-motion:reduce){.flip{transition:none}}
 </style></head><body><div class="note">A LITTLE GARDEN, JUST FOR YOU</div><div class="wrap" tabindex="0" role="group" aria-label="花朵卡片"><div class="tilt"><div class="flip"><div class="face"><div class="board"><h1></h1></div></div><div class="face backface"><div class="board back-board"><img class="back-background" alt="写给你的祝福"></div></div></div></div></div><div class="actions"><button id="flip-button">读一读祝福 ↻</button></div><div class="signature"></div><div class="hint">移动光标，让花轻轻摇摆 · 点击按钮翻面</div>
 <script type="application/json" id="card-data">${encoded}</script><script>
 const data=JSON.parse(document.getElementById('card-data').textContent),s=data.state,dark=s.theme==='dark',paper=dark?'#11130f':'#f4f4ef',ink=dark?'#f4f3e9':'#191b16';document.body.style.background=paper;document.body.style.color=ink;document.querySelectorAll('.face').forEach(e=>e.style.background=paper);document.title='送给'+(s.to||'你')+'的一束花';document.querySelector('h1').textContent=s.title||'Gift Card';document.querySelector('h1').style.fontSize=(s.title.length>14?Math.max(75,200*14/s.title.length):200)+'px';document.querySelector('.signature').textContent='With love, '+(s.from||'我');document.querySelector('.back-background').src=data.back;const board=document.querySelector('.board'),wrap=document.querySelector('.wrap'),tilt=document.querySelector('.tilt'),flip=document.querySelector('.flip');for(const [side,list] of [['front',data.layers],['back',data.backLayers]])list.forEach(layer=>{const img=document.createElement('img');img.src=layer.url;img.className='layer';img.alt='';img.dataset.depth=layer.depth;img.dataset.side=side;(side==='front'?board:document.querySelector('.back-board')).append(img)});const resize=()=>document.querySelectorAll('.board').forEach(el=>el.style.transform='scale('+wrap.clientWidth/1200+')');new ResizeObserver(resize).observe(wrap);resize();let back=false;document.getElementById('flip-button').onclick=()=>{back=!back;flip.classList.toggle('back',back);document.getElementById('flip-button').textContent=back?'再看看花园 ↻':'读一读祝福 ↻'};const reduced=matchMedia('(prefers-reduced-motion:reduce)');let tx=0,ty=0,x=0,y=0,frame=0;function animate(){x+=(tx-x)*.12;y+=(ty-y)*.12;tilt.style.transform='rotateX('+(-y*9)+'deg) rotateY('+(x*9)+'deg)';document.querySelectorAll('.layer').forEach(e=>{e.style.transform='translate('+(e.dataset.side==='back'?-x:x)*Number(e.dataset.depth)*.18+'px,'+y*Number(e.dataset.depth)*.18+'px)'});if(Math.abs(tx-x)+Math.abs(ty-y)>.001)frame=requestAnimationFrame(animate);else frame=0}function start(){if(!frame)frame=requestAnimationFrame(animate)}wrap.onpointermove=e=>{if(reduced.matches||e.pointerType==='touch')return;const r=wrap.getBoundingClientRect();tx=(e.clientX-r.left)/r.width*2-1;ty=(e.clientY-r.top)/r.height*2-1;start()};wrap.onpointerleave=()=>{tx=ty=0;start()};reduced.addEventListener('change',()=>{tx=ty=x=y=0;tilt.style.transform='none';document.querySelectorAll('.layer').forEach(e=>e.style.transform='none')});
 <\/script></body></html>`;
 const blob=new Blob([html],{type:'text/html;charset=utf-8'});if(download)downloadBlob(blob,'给'+(state.to||'你')+'的一束花.html');return blob;
}
